package domain_test

import (
	"os"
	"strings"
	"testing"

	"github.com/federiconbaez/cortex9-sqlite-forensics-mcp/internal/domain"
	"github.com/federiconbaez/cortex9-sqlite-forensics-mcp/internal/synth"
)

// Golden tests: SYNTHETIC databases are generated by the real SQLite engine
// (modernc.org/sqlite) and the pure parsers must agree with it.

func TestGoldenFreelistDatabase(t *testing.T) {
	fx, err := synth.BuildFreelistDB(t.TempDir(), 400, 250)
	if err != nil {
		t.Fatal(err)
	}
	img, err := os.ReadFile(fx.Path)
	if err != nil {
		t.Fatal(err)
	}
	h, err := domain.ParseHeader(img)
	if err != nil {
		t.Fatal(err)
	}
	for name, got := range map[string]int64{
		"page_size":      int64(h.PageSize),
		"freelist_count": int64(h.FreelistPageCount),
		"schema_version": int64(h.SchemaCookie),
		"page_count":     int64(domain.PageCount(h, len(img))),
	} {
		want, err := synth.Pragma(fx.Path, name)
		if err != nil {
			t.Fatal(err)
		}
		if got != want {
			t.Errorf("%s: parser %d, sqlite %d", name, got, want)
		}
	}
	if h.FreelistPageCount == 0 {
		t.Fatal("fixture must have freelist pages")
	}
	fl, err := domain.WalkFreelist(img, h)
	if err != nil || !fl.CountMatches {
		t.Fatalf("freelist %+v %v", fl, err)
	}
	res := domain.CarveDatabase(img, h, fl, domain.CarveOptions{})
	deleted := map[string]bool{}
	for _, id := range fx.Deleted {
		deleted[synth.Marker(id)] = true
	}
	recovered := map[string]domain.Confidence{}
	for _, c := range res.Candidates {
		for _, v := range c.Record.Values {
			if v.Kind == domain.KindText && strings.HasPrefix(string(v.Bytes), "SYNTH-MSG-") {
				m := string(v.Bytes)[:len("SYNTH-MSG-0000")]
				if c.Confidence > recovered[m] {
					recovered[m] = c.Confidence
				}
			}
		}
	}
	hits, high := 0, 0
	for m := range deleted {
		if conf, ok := recovered[m]; ok {
			hits++
			if conf == domain.ConfidenceHigh {
				high++
			}
		}
	}
	recall := float64(hits) / float64(len(deleted))
	t.Logf("deleted=%d recovered=%d (%.1f%%) high=%d candidates=%d freelist_pages=%d overflow=%d",
		len(deleted), hits, 100*recall, high, len(res.Candidates), res.FreelistPages, res.OverflowCells)
	if recall < 0.9 {
		t.Fatalf("recall %.2f below 0.90", recall)
	}
	tl := domain.BuildTimeline(res.Candidates, domain.DefaultWindow())
	if len(tl) == 0 {
		t.Fatal("expected timestamps from sent_at / read_at")
	}
}

func TestGoldenWAL(t *testing.T) {
	fx, err := synth.BuildWALDB(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	walBytes, err := os.ReadFile(fx.WALPath)
	if err != nil {
		t.Fatal(err)
	}
	db, err := os.ReadFile(fx.DBPath)
	if err != nil {
		t.Fatal(err)
	}
	w, err := domain.ParseWAL(walBytes)
	if err != nil {
		t.Fatal(err)
	}
	if !w.Header.ChecksumValid || w.Header.PageSize != uint32(fx.PageSize) {
		t.Fatalf("header %+v", w.Header)
	}
	if w.CommitFrames != fx.Transactions || w.ValidFrames != w.CommittedFrames || w.ValidFrames == 0 {
		t.Fatalf("commits=%d want %d valid=%d committed=%d frames=%d stale=%d", w.CommitFrames, fx.Transactions, w.ValidFrames, w.CommittedFrames, len(w.Frames), w.StaleSaltFrames)
	}
	h, err := domain.ParseHeader(db)
	if err != nil || h.WriteVersion != 2 {
		t.Fatalf("WAL-mode header %+v %v", h, err)
	}
	differs := 0
	for _, s := range domain.SummarizeWALPages(w, db, h.PageSize) {
		if s.Status == domain.DiffDiffers || s.Status == domain.DiffBeyondDB {
			differs++
		}
	}
	if differs == 0 {
		t.Fatal("uncheckpointed WAL must hold pages that differ from the main file")
	}
	t.Logf("frames=%d valid=%d commits=%d pages-differing=%d", len(w.Frames), w.ValidFrames, w.CommitFrames, differs)
}
